  const COVERAGE_ROW = function (line) {
    const p = String(line).split('|');
    const split = function (s) {
      return String(s || '')
        .split(',')
        .map(function (x) { return x.trim(); })
        .filter(Boolean);
    };
    return [p[0], p[1], split(p[2]), split(p[3])];
  };

