  // ── 日常高频零件（本轮追加）────────────────────────────────
  // 只补独立概念；同类口语说法挂 alias。重点补 object / pose / subject / mood，
  // 让「谁在什么旁边做什么」由少量零件组装，而不是为每个整句新增词条。
  Object.keys(COVERAGE_GROUPS).forEach(function (category) {
    COVERAGE_GROUPS[category] = COVERAGE_GROUPS[category].map(COVERAGE_ROW);
  });

